paragraph.math:
$${curl}\mathbf{F} = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  \frac{\partial}{\partial x} & \frac{\partial}{\partial y} & \frac{\partial}{\partial z} \\
  {- y^{2}} & x & z^{2}
  \end{matrix} \right| = \left( {1 + 2y} \right)\mathbf{k}$$

$$\begin{array}{l}
  {\iint\limits_{S}{{curl}\mathbf{F} \cdot d\mathbf{S} = {\int_{C}{\mathbf{F} \cdot d\mathbf{r} = {\int_{0}^{2\pi}{\mathbf{F}\left( {\mathbf{r}(t)} \right) \cdot \mathbf{r}^{\prime}(t)dt}}}}}} \\
  {{\phantom{\iint\limits_{S}{{curl}\mathbf{F} \cdot d\mathbf{S}}} = {\int_{0}^{2\pi}{{({- \sqrt{3}\cos t\sin t + \sqrt{3}\sin t\cos t})}dt}}} = \sqrt{3}{\int_{0}^{2\pi}{0dt = 0}}}
  \end{array}$$

$$\begin{array}{l}
  {\int_{C_{a}}\mathbf{v} \cdot d\mathbf{r} = {\iint\limits_{S_{a}}{{curl}\mathbf{v} \cdot d\mathbf{S} = {\iint\limits_{S_{a}}{{curl}\mathbf{v} \cdot \mathbf{n}dS}}}}} \\
  {\phantom{\int_{C_{a}}\mathbf{v} \cdot d\mathbf{r}} \approx {\iint\limits_{S_{a}}{{curl}\mathbf{v}\left( P_{0} \right) \cdot \mathbf{n}\left( P_{0} \right)dS = {curl}\mathbf{v}\left( P_{0} \right) \cdot \mathbf{n}\left( P_{0} \right)\pi a^{2}}}}
  \end{array}$$
